            optimization_level: 3,
            cache_enabled: true,
            loop_unrolling: true,
            constant_folding: true,
        };

        // O0: No optimization
        if opt.optimization_level < 1 {
            return bytecode;
        }

        // O1: Basic constant folding
        if opt.optimization_level >= 1 {
            bytecode = opt.constant_folding_pass(bytecode);
        }

        // O2: Loop unrolling
        if opt.optimization_level >= 2 {
            bytecode = opt.loop_unrolling_pass(bytecode);
        }

        // O3: Full optimization
        if opt.optimization_level >= 3 {
            bytecode = opt.dead_code_elimination_pass(bytecode);
            bytecode = opt.instruction_scheduling_pass(bytecode);
        }

        return bytecode;
    }

    fn constant_folding_pass(bytecode: any) -> any {
